"""
Create a recurring job named `heartbeatd45c2d` on Hopsworks that runs `data/heartbeat.py` periodically.
"""
import hopsworks
import os

# Connect to Hopsworks
project = hopsworks.login()
jobs = project.get_jobs_api()

# Define the job
job_name = "heartbeatd45c2d"
job_config = {
    "name": job_name,
    "job_type": "PYTHON",
    "enabled": True,
    "schedule": {
        "cron_expression": "0 * * * *",  # Hourly
        "enabled": True,
    },
    "python": {
        "file": "data/heartbeat.py",
        "main_class": None,
    },
    "config": {
        "run_config": {
            "environment": {},
        }
    }
}

# Create or update the job
try:
    jobs.create_job(job_config)
    print(f"Job '{job_name}' created successfully.")
except Exception as e:
    print(f"Error creating job: {e}")
    # If the job already exists, update it
    try:
        job = jobs.get_job(job_name)
        jobs.update_job(job_name, job_config)
        print(f"Job '{job_name}' updated successfully.")
    except Exception as update_e:
        print(f"Error updating job: {update_e}")
        raise

# Trigger a run to ensure it works
try:
    job = jobs.get_job(job_name)
    execution = job.run()
    print(f"Triggered run for job '{job_name}'. Execution ID: {execution.id}")

    # Wait for the run to complete (optional, but ensures the job works)
    execution.wait()
    print(f"Run completed with state: {execution.state}")
except Exception as e:
    print(f"Error running job: {e}")
    raise

